body:
> I already had a look at FileAccessHandler.kt but SparseArray shouldn't be able to cause an out of bound exception on an add function. AIs are saying it could be a threading problem

Might be the case. It is used from C++ code, `FileAccessFilesystemJAndroid` class (`platform/android/file_access_filesystem_jandroid.cpp`) and seems like there are no interlocking, so it's likely not thread safe. Try adding a lock for the `files` reads/writes:

<details>
  <summary>diff</summary>

```diff
diff --git a/platform/android/java/lib/src/org/godotengine/godot/io/file/FileAccessHandler.kt b/platform/android/java/lib/src/org/godotengine/godot/io/file/FileAccessHandler.kt
index 1e2f3ca06c..cba2537a66 100644
--- a/platform/android/java/lib/src/org/godotengine/godot/io/file/FileAccessHandler.kt
+++ b/platform/android/java/lib/src/org/godotengine/godot/io/file/FileAccessHandler.kt
@@ -110,8 +110,13 @@ class FileAccessHandler(val context: Context) {
 	internal val storageScopeIdentifier = StorageScope.Identifier(context)
 	private val files = SparseArray<DataAccess>()
 	private var lastFileId = STARTING_FILE_ID
+	private val lock = Any()

-	private fun hasFileId(fileId: Int) = files.indexOfKey(fileId) >= 0
+	private fun hasFileId(fileId: Int): Boolean {
+		synchronized(lock) {
+			return files.indexOfKey(fileId) >= 0
+		}
+	}

 	fun canAccess(filePath: String?): Boolean {
 		return storageScopeIdentifier.canAccess(filePath)
@@ -145,8 +150,9 @@ class FileAccessHandler(val context: Context) {
 		return try {
 			path?.let {
 				val dataAccess = DataAccess.generateDataAccess(storageScope, context, it, accessFlag) ?: return FILE_OPEN_FAILED
-
-				files.put(++lastFileId, dataAccess)
+				synchronized(lock) {
+					files.put(++lastFileId, dataAccess)
+				}
 				Pair(Error.OK, lastFileId)
 			} ?: FILE_OPEN_FAILED
 		} catch (e: FileNotFoundException) {
@@ -164,7 +170,9 @@ class FileAccessHandler(val context: Context) {
 			return 0L
 		}

-		return files[fileId].size()
+		synchronized(lock) {
+			return files[fileId].size()
+		}
 	}

 	fun fileSeek(fileId: Int, position: Long) {
@@ -172,7 +180,9 @@ class FileAccessHandler(val context: Context) {
 			return
 		}

-		files[fileId].seek(position)
+		synchronized(lock) {
+			files[fileId].seek(position)
+		}
 	}

 	fun fileSeekFromEnd(fileId: Int, position: Long) {
@@ -180,7 +190,9 @@ class FileAccessHandler(val context: Context) {
 			return
 		}

-		files[fileId].seekFromEnd(position)
+		synchronized(lock) {
+			files[fileId].seekFromEnd(position)
+		}
 	}

 	fun fileRead(fileId: Int, byteBuffer: ByteBuffer?): Int {
@@ -188,7 +200,9 @@ class FileAccessHandler(val context: Context) {
 			return 0
 		}

-		return files[fileId].read(byteBuffer)
+		synchronized(lock) {
+			return files[fileId].read(byteBuffer)
+		}
 	}

 	fun fileWrite(fileId: Int, byteBuffer: ByteBuffer?): Boolean {
@@ -196,7 +210,9 @@ class FileAccessHandler(val context: Context) {
 			return false
 		}

-		return files[fileId].write(byteBuffer)
+		synchronized(lock) {
+			return files[fileId].write(byteBuffer)
+		}
 	}

 	fun fileFlush(fileId: Int) {
@@ -204,7 +220,9 @@ class FileAccessHandler(val context: Context) {
 			return
 		}

-		files[fileId].flush()
+		synchronized(lock) {
+			files[fileId].flush()
+		}
 	}

 	fun getInputStream(path: String?) = Companion.getInputStream(context, storageScopeIdentifier, path)
@@ -248,7 +266,9 @@ class FileAccessHandler(val context: Context) {
 			return Error.FAILED.toNativeValue()
 		}

-		return files[fileId].resize(length).toNativeValue()
+		synchronized(lock) {
+			return files[fileId].resize(length).toNativeValue()
+		}
 	}

 	fun fileSize(filepath: String?): Long {
@@ -271,7 +291,9 @@ class FileAccessHandler(val context: Context) {
 			return 0L
 		}

-		return files[fileId].position()
+		synchronized(lock) {
+			return files[fileId].position()
+		}
 	}

 	fun isFileEof(fileId: Int): Boolean {
@@ -283,14 +305,18 @@ class FileAccessHandler(val context: Context) {
 	}

 	fun setFileEof(fileId: Int, eof: Boolean) {
-		val file = files[fileId] ?: return
-		file.endOfFile = eof
+		synchronized(lock) {
+			val file = files[fileId] ?: return
+			file.endOfFile = eof
+		}
 	}

 	fun fileClose(fileId: Int) {
-		if (hasFileId(fileId)) {
-			files[fileId].close()
-			files.remove(fileId)
+		synchronized(lock) {
+			if (hasFileId(fileId)) {
+				files[fileId].close()
+				files.remove(fileId)
+			}
 		}
 	}
 }
